import { visit } from 'unist-util-visit';
const MEDIA_ATTRIBUTES = new Set(['src', 'srcSet', 'srcset', 'poster', 'img', 'image']);
const prefix = (value, basePath) => value.startsWith('/') && !value.startsWith('//') ? `${basePath}${value}` : value;
const prefixSrcSet = (value, basePath) => value
    .split(',')
    .map((candidate) => {
    const trimmed = candidate.trim();
    const [url = '', ...descriptors] = trimmed.split(/\s+/);
    return [prefix(url, basePath), ...descriptors].join(' ');
})
    .join(', ');
export const remarkPrefixMediaBasePath = ({ basePath }) => {
    return (tree) => {
        if (!basePath)
            return;
        visit(tree, 'image', (node) => {
            node.url = prefix(node.url, basePath);
        });
        const prefixAttributes = (element) => {
            for (const attribute of element.attributes) {
                if (attribute.type !== 'mdxJsxAttribute' ||
                    !MEDIA_ATTRIBUTES.has(attribute.name) ||
                    typeof attribute.value !== 'string') {
                    continue;
                }
                attribute.value =
                    attribute.name.toLowerCase() === 'srcset'
                        ? prefixSrcSet(attribute.value, basePath)
                        : prefix(attribute.value, basePath);
            }
        };
        visit(tree, 'mdxJsxFlowElement', (node) => prefixAttributes(node));
        visit(tree, 'mdxJsxTextElement', (node) => prefixAttributes(node));
    };
};
